def test_login_returns_no_password(client, test_user):
    response = client.post("/api/auth/login", json={
        "email": test_user['email'],
        "password": test_user['password']
    })
    assert response.status_code == 200
    data = response.json()
    assert 'password' not in data

def test_category_validation_on_expense_create(client, token_headers):
    invalid_payload = {
        "amount": 100,
        "category": "InvalidCategory",
        "date": "2023-10-05"
    }
    response = client.post("/api/expenses", json=invalid_payload, headers=token_headers)
    assert response.status_code == 422

def test_user_can_only_delete_own_expenses(client, test_user, another_user_expense, token_headers):
    response = client.delete(f"/api/expenses/{another_user_expense.id}", headers=token_headers)
    assert response.status_code == 403

test('Expense form date defaults to today', () => {
    render(<AddExpense />);
    const dateInput = screen.getByLabelText(/date/i);
    const today = new Date().toISOString().split('T')[0];
    expect(dateInput).toHaveValue(today);
});

test('Category dropdown includes required options', () => {
    render(<AddExpense />);
    const categorySelect = screen.getByLabelText(/category/i);
    expect(categorySelect).toHaveTextContent('Food');
    expect(categorySelect).toHaveTextContent('Transport');
    expect(categorySelect).toHaveTextContent('Utilities');
    expect(categorySelect).toHaveTextContent('Entertainment');
    expect(categorySelect).toHaveTextContent('Health');
});
